    :param height: Height of the image.
    :param width: Width of the image.
    :param point: The current point.
    :return:
    """
def adjustEdges(height: Any, width: Any, point: Any) -> object {
    newPoint = [point[0], point[1]];
    if (point[0] >= height) {
        newPoint[0] = height - 1;
    }
    if (point[1] >= width) {
        newPoint[1] = width - 1;
    }
    return `tuple(newPoint);
}

